#!/usr/bin/env bash
#
# This is a STARTING POINT, not an answer. Copy the whole EXAMPLE folder to
# submissions/<your-github-username>/ and work in your copy.
#
# Do not edit this file. It is ignored when marking.

set -euo pipefail

dir="${1:?usage: report.sh <directory>}"
echo "FILES: $(find "$dir" -type f | wc -l)"

echo "DIRS: $(find "$dir" -mindepth 1 -type d | wc -l)"

echo "LARGEST:"
find "$dir" -type f | while read -r path; do
    echo "$(wc -c < "$path") ${path#"$dir"/}"
done | sort -nr | awk 'NR<=3'
# three lines, each "<bytes> <path>", biggest first

echo "EXECUTABLE:"
find "$dir" -type f | while read -r path; do
    if [[ -x "$path" ]]; then
    echo "${path#"$dir"/}"
    fi
done | sort
# one path per line, alphabetical

echo "EXTENSIONS:"
find "$dir" -type f | while read -r path; do
  name="${path##*/}"
  if [[ "$name" == *.* ]]; then
    echo ".${name##*.}"
  fi
done | sort | uniq -c | sort -nr | awk 'NR<=5'
# five lines, each "<count> <extension>", commonest first
